package io.knowledgebrain.learning;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;import org.springframework.http.MediaType;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
class CourseSharingClientTest {
 CourseContextClientTest f;
 @BeforeEach void setup(){f=new CourseContextClientTest();f.setup();}
 String response(){return "{\"learning\":"+f.response()+",\"policyVersion\":3,\"enabled\":true,\"audience\":\"OWNER\",\"membershipVersion\":2,\"eligibleParticipants\":[]}";}
 @Test void singletonCookieTraceAndFixedReadOnlyPostDoNotForwardActorHeaders(){f.server.expect(r->{assertEquals(org.springframework.http.HttpMethod.POST,r.getMethod());assertEquals("/api/groups/"+f.group+"/courses/"+f.course+"/progress-sharing-context",r.getURI().getPath());assertEquals("__Host-brain_guest="+f.token,r.getHeaders().getFirst("Cookie"));assertEquals(f.trace,r.getHeaders().getFirst("traceparent"));assertNull(r.getHeaders().getFirst("Authorization"));assertNull(r.getHeaders().getFirst("Origin"));}).andRespond(withSuccess(response(),MediaType.APPLICATION_JSON));var a=f.client.sharing(f.group,f.course,f.token,f.trace,List.of());assertEquals(3,a.policyVersion());assertTrue(a.enabled());f.server.verify();}
 @Test void malformedOversizedAndForeignAuthorityFailsClosed(){for(var v:List.of(response()+" {}",response().replace("policyVersion\":3","policyVersion\":3.5"),response().replace("membershipVersion\":2","membershipVersion\":0"),response().replace("audience\":\"OWNER","audience\":\"PUBLIC"),response().replace(f.group.toString(),f.space.toString()),response().replace("eligibleParticipants\":[]","eligibleParticipants\":[{}]"),response().replace("}",",\"enabled\":false}")," ".repeat(98305))){f.server.reset();f.server.expect(r->{}).andRespond(withSuccess(v,MediaType.APPLICATION_JSON));assertEquals(503,assertThrows(ResponseStatusException.class,()->f.client.sharing(f.group,f.course,f.token,f.trace,List.of())).getStatusCode().value());f.server.verify();}}
 @Test void freshDenialsPropagateAndRedirectsFailClosed(){for(var code:List.of(HttpStatus.UNAUTHORIZED,HttpStatus.FORBIDDEN,HttpStatus.NOT_FOUND,HttpStatus.FOUND)){f.server.reset();f.server.expect(r->{}).andRespond(withStatus(code));assertEquals(code==HttpStatus.FOUND?503:code.value(),assertThrows(ResponseStatusException.class,()->f.client.sharing(f.group,f.course,f.token,f.trace,List.of())).getStatusCode().value());f.server.verify();}}
}
